args.sql:
SELECT json_agg(
        json_build_object(
            'station_name', trim(o.observstation),
            'aoi_value', ROUND(CAST(o.atmostransparency * (1 - o.humidityrate/100.0) * (1 - 0.02 * o.windspeedms) AS numeric), 4),
            'lunar_factors', json_build_object(
                'lunar_stage', o.lunarstage,
                'lunar_distance', o.lunardistdeg
            ),
            'solar_condition', o.solarstatus
        ) ORDER BY trim(o.observstation)
    ) as environmental_factors
FROM observatories o
LIMIT 1;

